  const current=editing.value,{row,text}=current;editBusy.value=true;editError.value=''
  if(!editIntent||editIntent.rowId!==row.id||editIntent.revision!==row.revision||editIntent.text!==text)editIntent={rowId:row.id,revision:row.revision,text,operationId:crypto.randomUUID(),variant:{id:crypto.randomUUID(),text,taskId:null,state:'complete',createdAt:new Date().toISOString(),editedFrom:row.value.selectedVariantId}}
  const intent=editIntent
  try{
    let ok=await updateMessage(row,{...row.value,variants:[...row.value.variants,intent.variant],selectedVariantId:intent.variant.id},intent.operationId)
    if(!ok){try{const stored=await store.vault?.read<ChatMessage>(row.id),candidate=stored?.value.variants.find(v=>v.id===intent.variant.id);if(candidate&&candidate.text===intent.text&&candidate.createdAt===intent.variant.createdAt&&candidate.editedFrom===intent.variant.editedFrom){await loadMessages();ok=true;error.value=''}}catch{/* Retain the input until its actual saved candidate can be confirmed. */}}
    if(editing.value!==current)return;if(ok)editing.value=null;else{editError.value=error.value||'暂时没有保存成功';editConflict.value=true}
  }
  finally{editBusy.value=false}
}
async function recheckEdit(){
  const vault=store.vault,current=editing.value;if(!vault||!current||editBusy.value)return;editBusy.value=true
  try{const row=await vault.read<ChatMessage>(current.row.id);if(disposed||store.vault!==vault||!vault.unlocked||editing.value!==current)return;if(!row||row.kind!=='message'||row.value.sessionId!==sessionId)throw Error('这条消息已不可用，你的输入仍保留');current.row=row;editPeerText.value=selectedText(row.value);editIntent=null;editConflict.value=false;editError.value='';error.value=''}
  catch(e){editError.value=(e as Error).message}finally{editBusy.value=false}
}
async function fork(row:Document<ChatMessage>){const vault=store.vault,chat=session.value;if(!vault||!chat||active.value)return;busy.value=true;try{const id=crypto.randomUUID(),records=messages.value.slice(0,messages.value.findIndex(item=>item.id===row.id)+1),ids=records.map(()=>crypto.randomUUID()),next={...chat.value,title:chat.value.title+' · 另一条对话',messageIds:ids,currentTaskId:null,parent:{sessionId,messageId:row.id},createdAt:new Date().toISOString()};await vault.commitBundle(crypto.randomUUID(),[{kind:'session',id,expectedRevision:0,value:next},...records.map((item,i)=>({kind:'message' as const,id:ids[i]!,expectedRevision:0,value:{...item.value,sessionId:id}}))]);await router.push('/local/chat/'+id)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function replyEvent(event:'startup'|'session'|'user'|'assistant'|'member'){replyEventWork=replyEventWork.catch(()=>{}).then(async()=>{if(disposed||!session.value||!store.vault)return;try{replySets.value=await resolveReplies(store.vault,session.value.value);for(const set of replySets.value){if(!set.value.enabled||set.value.policy==='disabled')continue;for(const button of set.value.buttons.filter(row=>row.enabled&&row.triggers.includes(event))){if(replyQueue.length>=32)throw new Error('待确认快捷动作已达 32 项，请处理已有动作');replyQueue.push({set,button,manual:false})}}nextReply()}catch(e){if(!disposed)error.value=(e as Error).message}});await replyEventWork}
async function activateReply(choice:ReplyChoice,confirmed=false){const vault=store.vault,chat=session.value;if(!vault||!chat||replyBusy.value||choice.set.value.policy==='disabled'||!choice.set.value.enabled)return;const current=await vault.read<QuickReplySet>(choice.set.id);if(!current||current.revision!==choice.set.revision||!current.value.buttons.some(button=>button.id===choice.button.id&&button.enabled)){error.value='按钮设置已变化，请重新打开会话';return}if(!choice.manual&&!confirmed||choice.set.value.policy==='confirm'&&!confirmed){replyConfirm.value=choice;return}replyConfirm.value=null;replyBusy.value=true;replyController?.abort();const control=new AbortController();replyController=control;const signal=AbortSignal.any([control.signal,contextController.signal,AbortSignal.timeout(30000)]);error.value='';try{if(choice.set.value.policy==='fill'||!choice.button.text.trim().startsWith('/')){const member=chat.value.cards.find(row=>row.value.identityId===speaker.value)?.value;if(!member)throw new Error('请选择本会话的角色');const local=await vault.read<{values:Record<string,string|number>}>('variables:session:'+sessionId),global=await vault.read<{values:Record<string,string|number>}>('settings:global-variables'),last=(role?:string)=>{const row=[...messages.value].reverse().find(row=>!row.value.hidden&&(!role||row.value.role===role));return row?selectedText(row.value):''},now=new Date(),context:MacroContext={char:member.name,user:chat.value.persona.name,persona:chat.value.persona.description,description:chat.value.cards.length===1?member.description:'',personality:chat.value.cards.length===1?member.personality:'',scenario:chat.value.cards.length===1?member.scenario:'',mesExamples:chat.value.cards.length===1?member.exampleMessages:'',input:draft.value,lastMessage:last(),lastUserMessage:last('user'),lastCharMessage:last('assistant'),date:now.toISOString().slice(0,10),time:now.toISOString().slice(11,19),seed:crypto.randomUUID(),variables:local?.value.values||{},globalVariables:global?.value.values||{}};await scriptAuthority(vault,sessionId,[{setId:current.id,revision:current.revision,buttonId:choice.button.id}],signal);const text=expandMacros(choice.button.text,context).text;if(text.length>20000)throw new Error('草稿超过 20,000 字符');draft.value=text;await persistDraft();return}await runLocalScript(vault,sessionId,choice.button.text,{speakerId:()=>speaker.value,getInput:()=>draft.value,setInput:async text=>{signal.throwIfAborted();draft.value=text;await persistDraft()},reload:async role=>{signal.throwIfAborted();session.value=(await vault.read<ChatSession>(sessionId))!;await loadMessages();await follow();if(role==='user'||role==='assistant')void replyEvent(role)},echo:async text=>{signal.throwIfAborted();replyNotice.value=text},input:async text=>scriptQuestion(text,[],signal),buttons:async(text,labels)=>scriptQuestion(text,labels,signal),generate:async(_kind,control,sources)=>{if(task.value||busy.value)throw new Error('当前请求尚未结束，没有新增调用');await generate('continue',undefined,false,{sources,signal:control});const id=(task.value as Document<TextTask>|null)?.id;if(!id)throw new Error(error.value||'没有建立新请求');while(true){control.throwIfAborted();const row=await vault.read<TextTask>(id);if(!row)throw new Error('原请求记录缺失');if(['saved','failed','unknown','cancelled'].includes(row.value.status))return row.value.text;await new Promise<void>((resolve,reject)=>{const timer=setTimeout(resolve,100),abort=()=>{clearTimeout(timer);reject(control.reason)};control.addEventListener('abort',abort,{once:true});setTimeout(()=>control.removeEventListener('abort',abort),100)})}}},signal,{setId:current.id,revision:current.revision,buttonId:choice.button.id})}catch(e){if(!disposed&&!signal.aborted)error.value=(e as Error).message}finally{replyBusy.value=false;scriptDialog.value=null;dialogDone=null;nextReply()}}
function scriptQuestion(text:string,labels:string[],signal:AbortSignal){return new Promise<string>((resolve,reject)=>{if(signal.aborted){reject(signal.reason);return}scriptInput.value='';scriptDialog.value={text,labels};const abort=()=>{dialogDone=null;scriptDialog.value=null;reject(signal.reason)};signal.addEventListener('abort',abort,{once:true});dialogDone=value=>{signal.removeEventListener('abort',abort);dialogDone=null;scriptDialog.value=null;resolve(value)}})}
function cancelScript(){replyController?.abort(new DOMException('脚本已停止','AbortError'));scriptDialog.value=null}
watch(speaker,()=>{if(!loading.value)void replyEvent('member')})
let groupMutation=Promise.resolve()
async function pauseGroup(state:GroupRun['state']){const vault=store.vault,intentId=groupRun.value?.value.intentId;if(!vault)return;const work=groupMutation.catch(()=>{}).then(async()=>{for(let attempt=0;attempt<2;attempt++){const run=await vault.read<GroupRun>('group-run:'+sessionId);if(!run||intentId&&run.value.intentId!==intentId||run.value.state==='stopped'||run.value.state==='completed')return;try{await vault.commitBundle(crypto.randomUUID(),[{kind:'settings',id:run.id,expectedRevision:run.revision,value:{...run.value,state}}]);if(!disposed)groupRun.value=await vault.read<GroupRun>(run.id);return}catch(e){if((e as {code?:string}).code!=='REVISION_CONFLICT'||attempt===1)throw e}}});groupMutation=work;await work}
async function startGroup(resume=false){const vault=store.vault,chat=session.value;if(!vault||!chat||task.value||busy.value||chat.value.cards.length<3)return;try{const prior=await vault.read<GroupRun>('group-run:'+sessionId),snapshot=JSON.parse(JSON.stringify(chat.value.group||defaultGroup())) as GroupSettings;if(snapshot.mode==='specified'){error.value='请先在会话设置选择顺序、随机或自然编排';return}if(autoTurns.value<1||autoTurns.value>snapshot.maxAutomaticTurns||!Number.isSafeInteger(autoTurns.value))throw new Error('自动轮数超过本会话上限');const value:GroupRun=resume&&prior&&prior.value.started<prior.value.limit?{...prior.value,state:'running'}:{assetType:'group-run',intentId:crypto.randomUUID(),sessionId,limit:autoTurns.value,started:0,state:'running',snapshot,createdAt:new Date().toISOString()};await vault.commitBundle(crypto.randomUUID(),[{kind:'settings',id:'group-run:'+sessionId,expectedRevision:prior?.revision||0,value}],contextController.signal,[{id:sessionId,revision:chat.revision,kind:'session'}]);if(disposed||store.vault!==vault)return;groupRun.value=await vault.read<GroupRun>('group-run:'+sessionId);autoActive.value=true;await generate('continue',undefined,true)}catch(e){if(!disposed)error.value=(e as Error).message}}
async function nextGroup(){const vault=store.vault;if(!vault||disposed||!autoActive.value)return;groupRun.value=await vault.read<GroupRun>('group-run:'+sessionId);if(!groupRun.value||groupRun.value.value.state!=='running'){autoActive.value=false;return}if(groupRun.value.value.started>=groupRun.value.value.limit){autoActive.value=false;await pauseGroup('completed');return}await generate('continue',undefined,true)}
async function stopGroup(){autoActive.value=false;if(store.vault&&task.value)stopExecution(store.vault,task.value.id);try{await pauseGroup('stopped')}catch(e){if(!disposed)error.value=(e as Error).message}}
async function openSettings(){if(!session.value)return;const value=session.value.value;groupDraft.value=JSON.parse(JSON.stringify(value.group||defaultGroup()));settingsDraft.value={title:value.title,mode:value.mode,name:value.persona.name,description:value.persona.description,authorNote:value.authorNote,lorebookIds:[...(value.lorebookIds||[])],regexIds:[...(value.regexIds||[])],allowCardRegex:value.allowCardRegex===true,personaId:'',promptPresetId:value.promptPresetId===undefined?'inherit':value.promptPresetId||'standard',quickReplyIds:[...(value.quickReplyIds||[])]};allReplySets.value=store.vault?(await store.vault.list<QuickReplySet>('settings')).filter(row=>row.value.assetType==='quick-replies'):[];presets.value=store.vault?(await store.vault.list<PresetAsset>('settings')).filter(row=>row.value.assetType==='prompt-preset'):[];lorebooks.value=store.vault?await store.vault.list<LocalLorebook>('lorebook'):[];regexRules.value=store.vault?(await store.vault.list<RegexAsset>('settings')).filter(row=>row.value.assetType==='regex'):[];personas.value=store.vault?(await store.vault.list<Persona>('persona')).filter(row=>row.value.enabled):[];if(disposed)return;settings.value=true}
function adoptPersona(){const row=personas.value.find(row=>row.id===settingsDraft.value.personaId);if(row){settingsDraft.value.name=row.value.name;settingsDraft.value.description=row.value.description}}
async function saveSettings(){if(!store.vault||!session.value)return;try{if(session.value.value.cards.length>1)validateGroup(groupDraft.value,session.value.value.cards.map(row=>row.value.identityId));const value:ChatSession={...session.value.value,...(session.value.value.cards.length>1?{group:groupDraft.value}:{}),title:settingsDraft.value.title,mode:settingsDraft.value.mode as ChatSession['mode'],persona:{name:settingsDraft.value.name,description:settingsDraft.value.description},authorNote:settingsDraft.value.authorNote,lorebookIds:settingsDraft.value.lorebookIds,regexIds:settingsDraft.value.regexIds,allowCardRegex:settingsDraft.value.allowCardRegex,quickReplyIds:settingsDraft.value.quickReplyIds,promptPresetId:settingsDraft.value.promptPresetId==='standard'?null:settingsDraft.value.promptPresetId};if(settingsDraft.value.promptPresetId==='inherit')delete value.promptPresetId;await store.vault.commitBundle(crypto.randomUUID(),[{kind:'session',id:sessionId,expectedRevision:session.value.revision,value}],contextController.signal);if(disposed)return;session.value=(await store.vault.read<ChatSession>(sessionId))!;settings.value=false;replySets.value=await resolveReplies(store.vault,session.value.value);await loadMessages()}catch(e){error.value=(e as Error).message}}
function exportChat(){const text=exportChatJsonl(session.value!.value,messages.value),url=URL.createObjectURL(new Blob([text],{type:'application/x-ndjson'})),link=document.createElement('a');link.href=url;link.download=(session.value?.value.title||'对话')+'.jsonl';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function copyMessage(row:Document<ChatMessage>){try{await navigator.clipboard.writeText(selectedText(row.value))}catch{error.value='未获得剪贴板权限；可以选中文字复制'}}
async function inspect(){try{if(task.value){const trace=task.value.value.promptTrace;inspected.value={messages:task.value.value.request,estimatedInput:task.value.value.plan.estimatedInput,sources:Array.isArray(trace?.sources)?trace.sources as ReturnType<typeof chatPrompt>['sources']:[]}}else if(store.vault&&session.value){inspected.value=(await buildPrompt(session.value.value,messages.value,speaker.value)).prompt}if(!disposed)inspector.value=true}catch(e){if(!disposed)error.value=(e as Error).message}}
async function refreshGroup(){const vault=store.vault;if(!vault||disposed)return;try{const current=await vault.read<GroupRun>('group-run:'+sessionId);if(disposed||store.vault!==vault)return;groupRun.value=current;if(autoActive.value&&current?.value.state!=='running')autoActive.value=false}catch(e){if(!disposed)error.value=(e as Error).message}}
function stopReply(){if(groupRun.value?.value.state==='running')void stopGroup();else if(store.vault&&task.value)stopExecution(store.vault,task.value.id)}
onMounted(async()=>{await load();poll=setInterval(()=>{void refreshGroup();void pollTask()},2000)})
onBeforeRouteLeave(async()=>{if(autoActive.value){autoActive.value=false;try{await pauseGroup('paused')}catch(e){error.value=(e as Error).message;return false}}if(draftTimer)clearTimeout(draftTimer);await persistDraft();if(draft.value!==durableDraft){error.value='草稿还没有保存，请保留或复制这段文字后再离开';return false}})
onUnmounted(()=>{mediaLifecycle.abort();cancelScript();autoActive.value=false;disposed=true;contextController.abort();displayController?.abort();detach();if(poll)clearInterval(poll);if(draftTimer)clearTimeout(draftTimer)})
