<template><ChatShell ref="chatShell" :label="session?.value.title||'角色对话'" @scroll="onScroll"><template #header><header class="final-chat-header"><RouterLink :to="session?.value.companionId?'/local/companions/'+session.value.companionId:'/local/characters'" class="final-icon-button" :aria-label="session?.value.companionId?'返回伴侣':'返回角色'"><ArrowLeft :size="22"/></RouterLink><div class="final-chat-heading"><button class="chat-identity" aria-label="查看模型与身份" @click="openSettings"><strong>{{session?.value.title||'角色对话'}}</strong><small>{{session?.value.persona.name||'读者'}} · {{modelLabel}}</small></button></div><ActionMenu label="会话菜单"><template #trigger><MoreHorizontal :size="22"/></template><button @click="openSettings"><Settings2 :size="18"/>会话设置</button><button @click="inspect"><ScanText :size="18"/>上下文检查</button><RouterLink :to="'/local/chat-stage/'+sessionId" class="final-text-link"><Clapperboard :size="18"/>进入对话舞台</RouterLink><button :disabled="loading||busy||active" @click="saveConversation"><BookOpen :size="18"/>保存为阅读稿</button><RouterLink v-for="origin in storyOrigins" :key="origin.key" :to="origin.to" class="final-text-link"><BookOpen :size="18"/>{{origin.label}}</RouterLink><button @click="exportChat"><Download :size="18"/>导出 JSONL</button></ActionMenu></header></template><template #messages><p v-if="loading" role="status">正在打开对话…</p><p v-if="error" class="final-error" role="alert">{{error}}</p><article v-for="row in messages" :id="'message-'+row.id" :key="row.id" :class="['final-chat-message',row.value.role,{'is-hidden':row.value.hidden}]"><strong>{{row.value.role==='user'?row.value.personaName||session?.value.persona.name:session?.value.cards.find(card=>card.value.identityId===row.value.speakerId)?.value.name||'旁白'}}</strong><RichText :text="rendered[row.id]?.text??selectedText(row.value)"/><AssetLinks :target-id="row.id" target-kind="message" :target-revision="row.revision" role="attachment"/><AssetLinks :target-id="row.id" target-kind="message" :target-revision="row.revision" role="speech"/><details v-if="rendered[row.id]?.trace.some(item=>item.included)" class="final-message-source"><summary>文本来源</summary><pre class="final-task-prose">{{selectedText(row.value)}}</pre><small v-for="(item,index) in rendered[row.id]?.trace" :key="index">{{item.id}} · {{item.reason}}</small></details><div class="final-message-actions"><button class="final-icon-button" aria-label="复制消息" @click="copyMessage(row)"><Copy :size="16"/></button><ActionMenu :label="'更多消息操作 '+(messages.indexOf(row)+1)"><template #trigger><MoreHorizontal :size="18"/></template><button @click="messageMedia(row)">配图</button><button @click="messageMedia(row,'tts')">配音</button><button :disabled="active" class="final-icon-button" :aria-label="row.value.hidden?'恢复消息':'隐藏消息'" @click="updateMessage(row,{...row.value,hidden:!row.value.hidden})"><Eye v-if="row.value.hidden" :size="16"/><EyeOff v-else :size="16"/></button><button :disabled="active" @click="editing={row,text:selectedText(row.value)}">编辑</button><button :disabled="active||busy||!!task" class="final-icon-button" aria-label="从这条消息分叉" @click="fork(row)"><GitBranch :size="16"/></button><button v-if="row.value.role==='assistant'" :disabled="active||busy||!!task" class="final-icon-button" aria-label="重新生成候选" @click="regenerate(row)"><RotateCcw :size="16"/></button></ActionMenu><template v-if="row.value.variants.length>1"><button class="final-icon-button" aria-label="上一个候选" :disabled="active||row.value.variants[0]?.id===row.value.selectedVariantId" @click="choose(row,-1)"><ChevronLeft :size="16"/></button><small>{{row.value.variants.findIndex(v=>v.id===row.value.selectedVariantId)+1}} / {{row.value.variants.length}}</small><button class="final-icon-button" aria-label="下一个候选" :disabled="active||row.value.variants.at(-1)?.id===row.value.selectedVariantId" @click="choose(row,1)"><ChevronRight :size="16"/></button></template></div></article><article v-if="task" class="final-chat-message assistant"><strong>{{session?.value.cards.find(card=>card.value.identityId===task?.value.speakerId)?.value.name}}</strong><p>{{task.value.text||(task.value.status==='queued'?'请求已保存，等待开始':task.value.status==='running'?'正在等待回复…':'这次请求没有收到文字')}}</p><span class="final-subtle" role="status">{{task.value.error?.message||({queued:'待开始',running:'正在回复',paused:'已暂停',unknown:'响应待核对',received:'等待保存',saved:'已保存',failed:'未完成',cancelled:'已停止'})[task.value.status]}}</span><div class="final-grid-actions"><button v-if="task.value.status==='queued'" @click="runQueued">开始原请求</button><button v-if="task.value.text&&task.value.status!=='running'" :disabled="busy" @click="saveOutput">保留这段文字</button><button v-if="task.value.status!=='running'" :disabled="busy" @click="detachResult">保留请求记录并继续会话</button><button v-if="task.value.status==='unknown'&&task.value.configSnapshot.queryStoredResponse" :disabled="busy" @click="query">查询原请求</button></div></article></template><template #scroll-controls><button v-if="!following" @click="returnToBottom"><ArrowDown :size="16"/>{{newMessages?newMessages+' 条新消息':'回到底部'}}</button></template><template #composer><footer class="final-chat-composer"><ChatComposer v-model="draft" :disabled="loading" :can-send="!(loading||busy||replyBusy||task||!draft.trim())" :can-stop="task?.value.status==='running'" @send="generate()" @stop="stopReply"><template #above><label v-if="(session?.value.cards.length||0)>1">下一个发言角色<select v-model="speaker" :disabled="!!task"><option v-for="card in session?.value.cards" :key="card.value.identityId" :value="card.value.identityId" :disabled="session?.value.group?.disabledIds.includes(card.value.identityId)||session?.value.group?.probabilities[card.value.identityId]===0">{{card.value.name}}</option></select></label></template><template #tools><PluginTools v-if="session" :session-id="sessionId" :chat="session.value" :messages="messages" :speaker-id="speaker" @fill="draft=$event;persistDraft()"/><template v-for="set in replySets" :key="set.id"><template v-if="set.value.enabled&&set.value.policy!=='disabled'"><button v-for="button in set.value.buttons.filter(row=>row.enabled&&row.triggers.includes('manual'))" :key="button.id" :disabled="replyBusy" @click="activateReply({set,button,manual:true})">{{button.label}}</button></template></template><button v-if="replyBusy" @click="cancelScript">停止脚本</button><button v-if="!task&&messages.length" class="final-text-link" :disabled="busy" @click="generate('continue')">让 TA 继续说</button><div v-if="(session?.value.cards.length||0)>2" class="chat-group-controls"><template v-if="!autoActive"><label>自动轮数<input v-model.number="autoTurns" aria-label="自动轮数" type="number" min="1" :max="session?.value.group?.maxAutomaticTurns||6"></label><button :disabled="busy||!!task" @click="startGroup()">自动聊</button><button v-if="groupRun&&['running','paused'].includes(groupRun.value.state)&&groupRun.value.started<groupRun.value.limit" :disabled="busy||!!task" @click="startGroup(true)">继续剩余轮次</button></template><button v-if="autoActive||groupRun?.value.state==='running'" @click="stopGroup">停止自动</button><small v-if="groupRun">{{groupRun.value.started}} / {{groupRun.value.limit}} 轮</small></div><details v-if="draftCopies.length" class="final-draft-copies"><summary>另存的草稿 · {{draftCopies.length}}</summary><article v-for="copy in draftCopies" :key="copy.id"><p>{{copy.value.text}}</p><button @click="useDraftCopy(copy)">使用这份</button></article></details></template><template #status><p v-if="replyNotice" class="final-subtle" role="status">{{replyNotice}}</p></template></ChatComposer></footer></template><template #overlays><Sheet v-if="regenerateGuard" title="保留当前回复" @close="regenerateGuard=null"><p>{{regenerateGuard.text}}</p><div class="final-grid-actions"><button @click="regenerateGuard=null">取消</button><button class="final-primary" @click="regenerate(regenerateGuard!.row,true)">生成新候选</button></div></Sheet><Sheet v-if="replyConfirm" title="执行快捷动作" @close="dismissReply"><p>{{replyConfirm.button.label}}</p><pre class="final-task-prose">{{replyConfirm.button.text}}</pre><div class="final-grid-actions"><button @click="dismissReply">取消</button><button class="final-primary" @click="activateReply(replyConfirm!,true)">{{replyConfirm.set.value.policy==='fill'?'填入草稿':'执行此动作'}}</button></div></Sheet><Sheet v-if="scriptDialog" title="快捷动作" @close="cancelScript"><p>{{scriptDialog.text}}</p><div v-if="scriptDialog.labels.length" class="final-grid-actions"><button v-for="label in scriptDialog.labels" :key="label" @click="dialogDone?.(label)">{{label}}</button></div><form v-else @submit.prevent="dialogDone?.(scriptInput)"><input v-model="scriptInput" aria-label="脚本输入" maxlength="20000"><button class="final-primary">确认输入</button></form></Sheet><Sheet v-if="editing" title="编辑消息" @close="!editBusy&&(editing=null)"><form class="final-card-form" @submit.prevent="edited"><textarea v-model="editing.text" aria-label="消息内容" maxlength="1000000" :disabled="editBusy"></textarea><p v-if="editError" class="final-error" role="alert">{{editError}}。你的输入仍保留。</p><button v-if="editConflict" type="button" :disabled="editBusy" @click="recheckEdit">载入当前候选并保留输入</button><details v-if="editPeerText!==null" class="edit-peer-details"><summary>当前候选</summary><pre class="edit-peer-text">{{editPeerText}}</pre></details><button class="final-primary" :disabled="editBusy||editConflict||active">保存为新候选</button></form></Sheet><PromotionPanel v-if="promotionTarget" :target="promotionTarget" @close="promotionTarget=null"/><Sheet v-if="settings" title="会话设置" @close="settings=false"><button v-if="session&&session.value.cards.length===1&&!session.value.companionId" class="final-text-link" @click="promotionTarget={kind:'session',id:session.id,revision:session.revision};settings=false">转为伴侣</button><form class="final-card-form" @submit.prevent="saveSettings"><label>标题<input v-model="settingsDraft.title" maxlength="160" required></label><label>身份模式<select v-model="settingsDraft.mode"><option value="reader">故事外读者</option><option value="roleplay">故事内扮演</option></select></label><label v-if="personas.length">切换已存身份<select aria-label="切换已存身份" v-model="settingsDraft.personaId" @change="adoptPersona"><option value="">自定义</option><option v-for="persona in personas" :key="persona.id" :value="persona.id">{{persona.value.name}}</option></select></label><RouterLink :to="'/local/plugins?session='+sessionId" class="final-text-link">本会话插件</RouterLink><RouterLink to="/local/tavern/personas" class="final-text-link">管理我的身份</RouterLink><label>你的名字<input v-model="settingsDraft.name" maxlength="200" required></label><label>你的身份<textarea v-model="settingsDraft.description" maxlength="12000"></textarea></label><fieldset v-if="(session?.value.cards.length||0)>1"><legend>群聊编排</legend><label>发言方式<select aria-label="群聊发言方式" v-model="groupDraft.mode"><option value="specified">指定</option><option value="sequential">顺序</option><option value="random">随机</option><option value="natural">自然</option></select></label><div v-for="card in session?.value.cards" :key="card.value.identityId" class="final-grid-row"><label class="final-check"><input v-model="groupDraft.disabledIds" :value="card.value.identityId" type="checkbox">停用 {{card.value.name}}</label><label>发言权重<input v-model.number="groupDraft.probabilities[card.value.identityId]" :aria-label="card.value.name+'发言权重'" type="number" min="0" max="100" placeholder="100"></label></div><label>群聊方向<textarea v-model="groupDraft.director" maxlength="2000"></textarea></label><label>自动发言上限<input v-model.number="groupDraft.maxAutomaticTurns" type="number" min="1" max="12"></label></fieldset><fieldset v-if="allReplySets.length"><legend>本会话快捷按钮</legend><label v-for="set in allReplySets" :key="set.id" class="final-check"><input v-model="settingsDraft.quickReplyIds" type="checkbox" :value="set.id">{{set.value.name}}</label></fieldset><RouterLink to="/local/tavern/quick-replies" class="final-text-link">管理快捷按钮</RouterLink><label>提示预设<select aria-label="会话提示预设" v-model="settingsDraft.promptPresetId"><option value="inherit">继承角色与全局</option><option value="standard">标准叙事</option><option v-for="preset in presets" :key="preset.id" :value="preset.id">{{preset.value.name}}</option></select></label><RouterLink to="/local/tavern/presets" class="final-text-link">管理提示预设</RouterLink><label>作者注释<textarea v-model="settingsDraft.authorNote" maxlength="12000"></textarea></label><fieldset v-if="lorebooks.length"><legend>本会话世界书</legend><label v-for="book in lorebooks" :key="book.id" class="final-check"><input v-model="settingsDraft.lorebookIds" type="checkbox" :value="book.id">{{book.value.name}}</label></fieldset><RouterLink to="/local/lorebooks" class="final-text-link">管理世界书</RouterLink><fieldset v-if="regexRules.length"><legend>本会话正则</legend><label v-for="rule in regexRules" :key="rule.id" class="final-check"><input v-model="settingsDraft.regexIds" type="checkbox" :value="rule.id">{{rule.value.name}}</label></fieldset><label class="final-check"><input v-model="settingsDraft.allowCardRegex" type="checkbox">启用本卡内置正则</label><RouterLink to="/local/tavern/regex" class="final-text-link">管理正则</RouterLink><button class="final-primary">保存设置</button></form><button class="final-text-link" @click="exportChat"><Download :size="18"/>导出 JSONL</button></Sheet><Sheet v-if="inspector" title="上下文检查" @close="inspector=false"><div class="final-prompt-inspector"><p class="final-subtle">保守输入估算 {{inspected?.estimatedInput||task?.value.plan.estimatedInput}} token · 实际用量以请求回执为准</p><div v-for="source in inspected?.sources" :key="source.id"><span>{{source.included?'已包含':'未包含'}} · {{source.reason}}</span><small>{{source.id}} · {{source.characters}} 字符</small></div><details><summary>查看本人提示正文</summary><pre>{{task?task.value.request:inspected?.messages}}</pre></details><details v-if="task?.value.promptTrace?.plugins"><summary>已冻结插件与上下文影响</summary><pre>{{task.value.promptTrace.plugins}}</pre></details><details v-if="task?.value.promptTrace?.preset"><summary>已冻结预设</summary><pre>{{task.value.promptTrace.preset}}</pre></details><details v-if="task?.value.promptTrace?.regex"><summary>送模正则记录</summary><pre>{{task.value.promptTrace.regex}}</pre></details><details v-if="task"><summary>请求记录</summary><pre>{{taskPublicRecord(task)}}</pre></details></div></Sheet></template></ChatShell></template>

